from __future__ import annotations


def build_retirement_destination_finder_html(
    *,
    head: str,
    navigation: str,
    region_options: str,
    universe_count: int,
    payload_json: str,
    retirement_engine: str,
    property_engine: str,
    finder_engine: str,
    tax_scenario_engine: str,
    finder_ui: str,
    analytics: str,
    design_css: str,
    footer: str,
) -> str:
    html = """<!doctype html>
<html lang="en"><head>__HEAD__
<style>
:root{--ink:#23322d;--muted:#5d6c66;--paper:#f5f1e8;--card:#fffdf7;--line:#d8d4ca;--green:#386957;--brass:#9b762f}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:16px/1.5 Inter,Arial,sans-serif}a{color:#356b5b}.page-shell{width:min(1040px,calc(100% - 32px));margin:auto}.finder-hero{padding:0 0 48px;border-bottom:1px solid var(--line);background:linear-gradient(110deg,#fffdf7 0%,#f5f1e8 76%)}.page-nav{position:relative;min-height:82px;display:flex;align-items:center;justify-content:space-between;gap:24px}.page-brand img{width:112px;display:block}.page-nav-links{display:flex;gap:20px}.page-nav-links a{color:var(--ink);font-size:13px;font-weight:800;text-decoration:none}.mobile-menu{display:none}h1,h2,h3,legend{font-family:Georgia,serif;line-height:1.08}h1{max-width:780px;margin:54px 0 16px;font-size:clamp(44px,7vw,72px)}.lede{max-width:720px;margin:0;color:var(--muted);font-size:19px}.finder-modes{display:flex;gap:18px;margin-top:24px;font-weight:800}.finder-modes a[aria-current]{color:var(--ink);text-decoration:none;border-bottom:2px solid var(--brass)}main{padding:40px 0 72px}.finder-form,.finder-results{display:grid;gap:18px}.finder-section,.finder-results{padding:28px;border:1px solid var(--line);border-radius:10px;background:var(--card)}fieldset{min-width:0;margin:0;padding:0;border:0}legend,.finder-section h2,.finder-results h2{margin:0 0 8px;font-size:30px;font-weight:700}.section-help,.hint{margin:0 0 18px;color:var(--muted);font-size:14px}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.field{min-width:0}.field label{display:block;margin-bottom:6px;font-size:14px;font-weight:800}input,select{width:100%;min-height:44px;padding:9px 11px;border:1px solid #aca99f;border-radius:5px;background:#fff;color:var(--ink);font:inherit}.check{display:flex!important;gap:9px;align-items:center;margin-top:9px;font-size:14px}.check input{width:auto;min-height:auto}.tax-mode-choices{display:grid;gap:10px;margin-bottom:18px}.tax-mode-choice{display:grid!important;grid-template-columns:20px 1fr;gap:9px;align-items:start;margin:0!important}.tax-mode-choice input{width:20px;min-height:20px;margin-top:2px}.tax-mode-choice small{display:block;color:var(--muted);font-weight:400}[data-finder-group]{margin-top:20px;padding-top:20px;border-top:1px solid var(--line)}[hidden]{display:none!important}.finder-errors{padding:15px;border:1px solid #9e5f4a;background:#fff4ef}.finder-errors ul{margin:7px 0 0}.finder-submit{min-height:48px;border:0;border-radius:5px;background:var(--green);color:#fff;font:800 15px Inter,Arial,sans-serif;cursor:pointer}.finder-submit:disabled{opacity:.45;cursor:not-allowed}.privacy-note{margin:0;color:var(--muted);font-size:13px}.finder-results{margin-top:34px}.finder-summary{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin:20px 0 26px;border:1px solid var(--line)}.finder-summary div{padding:16px}.finder-summary div+div{border-left:1px solid var(--line)}.finder-summary span{display:block;color:var(--muted);font-size:12px}.finder-summary strong{display:block;margin-top:4px;font:700 28px Georgia,serif}.finder-projection-wrap{margin:0 0 30px;padding-bottom:24px;border-bottom:1px solid var(--line)}.finder-projection{position:relative;height:240px;padding-top:30px}.finder-projection-bars{height:180px;display:flex;align-items:end;gap:5px;border-bottom:1px solid var(--line)}.finder-chart-bar{flex:1;min-width:5px;border:0;background:var(--green);cursor:pointer;transform-origin:bottom;animation:finder-grow .45s ease both}.finder-chart-bar:focus{outline:3px solid #c99a40;outline-offset:2px}@keyframes finder-grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}.finder-chart-tooltip{position:absolute;top:0;right:0;padding:7px 9px;border:1px solid var(--line);background:#fff;font-size:13px}.finder-list{display:grid;gap:12px}.finder-result{padding:18px 0;border-top:1px solid var(--line)}.finder-result:first-child{border-top:0}.finder-result header{display:flex;justify-content:space-between;gap:20px;align-items:start}.finder-result h3{margin:2px 0;font-size:25px}.finder-result header a{white-space:nowrap;font-weight:800}.finder-tier{margin:0;color:var(--brass);font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.06em}.finder-place,.finder-financing,.finder-matches{margin:4px 0 0;color:var(--muted);font-size:13px}.finder-result dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:15px 0 0}.finder-result dt{color:var(--muted);font-size:11px}.finder-result dd{margin:2px 0 0;font-weight:800}.finder-evidence{margin-top:26px;border-top:1px solid var(--line);padding-top:20px}.finder-evidence summary{cursor:pointer;font-weight:800}.finder-evidence li{margin:8px 0}.method-note{margin-top:26px;color:var(--muted);font-size:13px}footer{padding:28px 0 42px;border-top:1px solid var(--line);color:var(--muted)}@media(max-width:760px){.page-nav-links{display:none}.mobile-menu{display:block}.mobile-menu>summary{display:flex;min-height:44px;align-items:center;cursor:pointer}.mobile-menu>nav{position:absolute;z-index:10;top:68px;right:0;width:min(280px,calc(100vw - 32px));padding:8px;border:1px solid var(--line);border-radius:6px;background:var(--card);box-shadow:0 12px 30px rgba(35,50,45,.16)}.mobile-menu>nav a{display:flex;min-height:44px;align-items:center;padding:8px 12px;color:var(--ink);font-weight:800;text-decoration:none}.field-grid,.finder-summary,.finder-result dl{grid-template-columns:1fr}.finder-summary div+div{border-left:0;border-top:1px solid var(--line)}.finder-projection{overflow-x:auto;overscroll-behavior-inline:contain;padding-bottom:8px}.finder-projection-bars{width:max(100%,var(--finder-chart-mobile-width))}.finder-chart-bar{min-width:44px}.finder-result header{display:block}.finder-result header a{display:flex;min-height:44px;align-items:center;margin-top:8px}.finder-section,.finder-results{padding:20px}}
.finder-results{min-width:0}.finder-projection-wrap{min-width:0}
</style><style id="gha-retirement-finder-design">__DESIGN_CSS__</style></head><body class="gha-mode-utility retirement-finder-page" data-design-system="gha-v1">
__NAV__<header class="finder-hero"><div class="page-shell"><p class="finder-eyebrow">Retirement planning tool</p><h1>Find destinations your retirement plan can support</h1><p class="lede">Start with the capital and monthly investing you have today. We project them to retirement, then compare every destination with complete cost data.</p><nav class="finder-modes" aria-label="Retirement calculator mode"><a href="/retirement-abroad-calculator/">Plan for a destination</a><a href="/retirement-destination-finder/" aria-current="page">Find destinations I can afford</a></nav></div></header>
<main id="retirement-destination-finder"><div class="page-shell"><form class="finder-form" id="retirement-destination-finder-form">
<fieldset class="finder-section" id="finder-current-resources"><span class="finder-step">Step 1 of 5</span><legend>What you have today</legend><p class="section-help">Use investable capital after debt and ordinary cash needs.</p><div class="field-grid">
<div class="field"><label for="finder-current-age">Current age</label><input id="finder-current-age" type="number" min="18" max="90" value="50" required></div><div class="field"><label for="finder-retirement-age">Planned retirement age</label><input id="finder-retirement-age" type="number" min="19" max="100" value="65" required></div>
<div class="field"><label for="finder-household">Household</label><select id="finder-household"><option value="single">Single</option><option value="couple" selected>Couple</option></select></div><div class="field"><label for="finder-horizon">Years in retirement</label><input id="finder-horizon" type="number" min="1" max="60" value="30" required></div>
<div class="field"><label for="finder-liquid-capital">Total liquid capital today (USD)</label><input id="finder-liquid-capital" type="number" min="0" step="1000" value="500000" required></div><div class="field"><label for="finder-monthly-contribution">Monthly amount invested (USD)</label><input id="finder-monthly-contribution" type="number" min="0" step="100" value="2000" required><label class="check"><input id="finder-contribution-indexed" type="checkbox" checked>Increase this with inflation</label></div>
<div class="field"><label for="finder-return">Expected annual portfolio return after fees and tax (%)</label><input id="finder-return" type="number" min="-5" max="15" step="0.1" value="5" required></div></div></fieldset>
<fieldset class="finder-section" id="finder-housing"><span class="finder-step">Step 2 of 5</span><legend>Housing plan</legend><p class="section-help">This changes both the capital allocation and destination target.</p><div class="field-grid"><div class="field"><label for="finder-housing-plan">At retirement I plan to</label><select id="finder-housing-plan"><option value="rent">Rent</option><option value="buy_now">Buy now</option><option value="buy_retirement">Buy at retirement</option><option value="own">Already own</option></select></div></div>
<p class="hint" id="finder-own-guidance" hidden>Because you already own the retirement home, the destination is known. <a href="/retirement-abroad-calculator/?housing=own">Plan for that destination instead</a>.</p>
<div data-finder-group="buyNow" hidden><div class="field-grid"><div class="field"><label for="finder-property-allocation">Maximum capital allocated to the purchase (USD)</label><input id="finder-property-allocation" type="number" min="0" step="1000" value="300000"></div><div class="field"><label for="finder-purchase-method">Purchase method</label><select id="finder-purchase-method"><option value="cash">Cash</option><option value="mortgage">Mortgage</option><option value="not_sure">Not sure</option></select></div><div class="field"><label for="finder-use-before-retirement">Use before retirement</label><select id="finder-use-before-retirement"><option value="personal">Personal or occasional use</option><option value="rental">Rent it out</option></select></div><div class="field"><label for="finder-mortgage-treatment">At retirement</label><select id="finder-mortgage-treatment"><option value="payoff">Pay off the remaining mortgage</option><option value="continue">Continue repayments</option></select></div></div></div>
<div data-finder-group="mortgage" hidden><div class="field-grid"><div class="field"><label for="finder-buyer-residency">Your status in the destination</label><select id="finder-buyer-residency"><option value="non_resident">Non-resident</option><option value="resident">Resident</option><option value="eu_national">EU national</option><option value="non_resident_with_purchase_permit">Non-resident with purchase permission</option></select></div><div class="field"><label for="finder-income-source">Income used to qualify</label><select id="finder-income-source"><option value="overseas">Overseas income</option><option value="documented_overseas_income">Documented overseas income</option><option value="eu_income">EU income</option><option value="japan_income">Japan income</option><option value="swiss_income">Swiss income</option></select></div><div class="field"><label for="finder-requested-ltv">Requested loan-to-value (%)</label><input id="finder-requested-ltv" type="number" min="0" max="100" step="1" value="60"></div><div class="field"><label for="finder-mortgage-rate">Illustrative annual mortgage rate (%)</label><input id="finder-mortgage-rate" type="number" min="0" max="25" step="0.1" value="5"></div><div class="field"><label for="finder-mortgage-term">Mortgage term (years)</label><input id="finder-mortgage-term" type="number" min="1" max="40" value="20"></div></div><p class="hint">Mortgage availability is indicative. The calculator constrains leverage using researched destination terms; lenders must confirm eligibility and pricing.</p></div>
<div data-finder-group="rental" hidden><div class="field-grid"><div class="field"><label for="finder-rental-yield">Illustrative gross rental yield (%)</label><input id="finder-rental-yield" type="number" min="0" max="30" step="0.1" value="5"></div><div class="field"><label for="finder-vacancy-rate">Vacancy allowance (%)</label><input id="finder-vacancy-rate" type="number" min="0" max="100" step="1" value="10"></div><div class="field"><label for="finder-operating-cost-rate">Management and operating costs (% of collected rent)</label><input id="finder-operating-cost-rate" type="number" min="0" max="100" step="1" value="20"></div></div></div><div data-finder-group="buyAtRetirement" hidden><p class="hint">The destination's projected purchase price and acquisition costs will be added to its retirement target.</p></div></fieldset>
<fieldset class="finder-section" id="finder-retirement-income"><span class="finder-step">Step 3 of 5</span><legend>Reliable annual income in retirement (USD)</legend><p class="section-help">Dependable annual income can include pensions and other non-portfolio income. Do not include portfolio dividends or interest here.</p><div class="field-grid"><div class="field"><label for="finder-pension">Pension</label><input id="finder-pension" type="number" min="0" step="1000" value="0"><label class="check"><input id="finder-pension-indexed" type="checkbox">Inflation-linked</label></div><div class="field"><label for="finder-other-income">Other dependable income</label><input id="finder-other-income" type="number" min="0" step="1000" value="0"><label class="check"><input id="finder-other-income-indexed" type="checkbox">Inflation-linked</label></div></div></fieldset>
<fieldset class="finder-section" id="finder-tax-planning"><span class="finder-step">Step 4 of 5</span><legend>Destination tax planning</legend><p class="section-help">These inputs prepare your tax profile but do not yet change finder rankings or retirement targets. Use the <a href="/retirement-abroad-calculator/">detailed calculator</a> for a tax-adjusted result.</p><div class="tax-mode-choices"><label class="tax-mode-choice"><input type="radio" name="finder-tax-mode" value="destination_estimate" checked><span>Use destination planning estimates<small>Record broad inputs for supported jurisdictions.</small></span></label><label class="tax-mode-choice"><input type="radio" name="finder-tax-mode" value="user_after_tax"><span>I know my after-tax figures<small>Record that your income and return already reflect tax.</small></span></label></div><div id="finder-tax-estimate-fields"><div class="field-grid"><div class="field"><label for="finder-tax-withdrawals">Expected annual portfolio withdrawals</label><input id="finder-tax-withdrawals" type="number" min="0" step="1000" value="0"></div><div class="field"><label for="finder-tax-gain-intensity">How much of those withdrawals may be realized gains?</label><select id="finder-tax-gain-intensity"><option value="low">Little or none</option><option value="moderate" selected>A moderate share</option><option value="high">A large share</option></select></div><div class="field" id="finder-tax-property-use-field" hidden><label for="finder-tax-property-use">How will you use the destination home?</label><select id="finder-tax-property-use" disabled><option value="personal" selected>Personal use</option><option value="rental">Rental</option><option value="mixed">Personal and rental use</option></select></div><div class="field" id="finder-tax-wealth-band-field"><label for="finder-tax-wealth-band">Broad household wealth band</label><select id="finder-tax-wealth-band"><option value="under_threshold">Below applicable destination thresholds</option><option value="above_threshold">Above an applicable destination threshold</option><option value="unknown" selected>Not sure</option></select><p class="hint">Used only for destinations where current evidence identifies a material wealth-tax exposure.</p></div></div></div><p class="hint" id="finder-tax-after-tax-note" hidden>Income and portfolio return must already reflect tax.</p></fieldset>
<fieldset class="finder-section" id="finder-preferences"><span class="finder-step">Step 5 of 5</span><legend>What matters to you</legend><p class="section-help">These preferences order destinations within the same financial tier.</p><div class="field-grid"><div class="field"><label for="finder-region">Region</label><select id="finder-region"><option value="any">No preference</option>__REGION_OPTIONS__</select></div><div class="field"><label for="finder-climate">Setting</label><select id="finder-climate"><option value="any">No preference</option><option value="City">City</option><option value="Water">Coast or island</option><option value="Mountain">Mountain</option><option value="Lake">Lake</option></select></div><div class="field"><label for="finder-healthcare">Healthcare importance</label><select id="finder-healthcare"><option value="normal">Important</option><option value="high">A leading priority</option></select></div></div></fieldset>
<div class="finder-errors" id="finder-errors" role="alert" tabindex="-1" hidden></div><button class="finder-submit" id="finder-submit" type="submit">Project my retirement and compare destinations</button><p class="privacy-note">Your financial details stay in this browser. They are not saved or sent to analytics.</p></form>
<noscript><p class="finder-section"><strong>The interactive destination comparison requires JavaScript.</strong> The tax controls below remain a planning checklist; review the static methodology and return when JavaScript is available.</p></noscript>
<section class="finder-results" id="finder-results" data-universe-count="__UNIVERSE_COUNT__" hidden aria-live="polite"><h2>Your retirement destination outlook</h2><p class="finder-result-read" id="finder-result-read"></p><p class="hint">Affordability is a planning estimate, not a guarantee.</p><div class="finder-summary"><div><span>Capital today</span><strong id="finder-capital-today">—</strong></div><div><span>Monthly investing</span><strong id="finder-monthly-summary">—</strong></div><div><span>Within reach</span><strong id="finder-within-count">—</strong></div><div><span>Closest match</span><strong id="finder-closest-match">—</strong></div></div>
<div class="finder-projection-wrap" id="finder-projection-wrap"><h3>Projected portfolio by year</h3><div class="finder-projection" id="finder-projection" role="img" aria-label="Year-by-year projected retirement portfolio"><div class="finder-chart-tooltip" id="finder-chart-tooltip" role="status" hidden><strong id="finder-tooltip-heading"></strong> <span id="finder-tooltip-value"></span></div><div class="finder-projection-bars" id="finder-projection-bars"></div></div></div><p class="hint" id="finder-buy-now-chart-note" hidden>Buying now produces a different portfolio projection for each destination, so those figures appear with each result.</p><div class="finder-list" id="finder-recommendations" aria-label="Recommended retirement destinations"></div><button class="finder-show-all" id="finder-show-all" type="button" aria-expanded="false" hidden>View all destinations</button><p class="method-note" id="finder-excluded-summary"></p><details class="finder-evidence" id="finder-exclusions" hidden><summary>Review excluded destinations</summary><ul id="finder-exclusion-list"></ul></details>
<details class="finder-evidence" id="finder-financing-evidence" hidden><summary>Mortgage evidence used</summary><ul id="finder-financing-evidence-list"></ul><p class="hint">Mortgage availability is indicative and must be verified with lenders.</p></details><p class="method-note">Within reach means projected liquid capital covers the modeled target. Close means 85–99%. Property equity is shown separately and never funds retirement spending in this comparison. <a href="/methodology/">Read the methodology</a>.</p></section>
<div class="finder-editorial">
<section id="how-matching-works"><h2>How the retirement destination finder works</h2><p>The finder projects your liquid portfolio to retirement using the ages, contributions and return you enter. It then compares that capital with each destination’s modeled living costs, emergency reserve and housing plan. Lifestyle preferences reorder destinations within the same affordability tier; they do not make an unaffordable plan appear affordable.</p></section>
<section id="within-reach"><h2>What “within reach” means</h2><p><strong>Projected liquid capital covers the modeled retirement target</strong> for the selected household, retirement duration and housing plan. “Close” means the projection covers 85–99% of the target. These are planning thresholds, not promises: tax, visa eligibility, healthcare circumstances and currency shocks still require separate advice.</p></section>
<section id="rent-or-buy"><h2>Renting versus buying in retirement</h2><div class="finder-comparison"><article><h3>Rent</h3><p>The target includes ongoing modeled rent and preserves property capital as liquid retirement assets. Renting is the cleaner first comparison when residency, neighborhood fit or long-term plans remain uncertain.</p></article><article><h3>Buy</h3><p><strong>Buying requires separate property capital</strong>, acquisition costs and a realistic financing assumption. Property equity is reported separately and is never counted as money available for retirement spending.</p></article></div></section>
<section class="finder-faq" id="finder-faq"><h2>Frequently asked questions</h2><details><summary>How does the finder choose retirement destinations?</summary><p>It first ranks destinations by whether projected liquid capital covers the modeled target, then uses region, setting and healthcare preferences to order destinations within each financial tier.</p></details><details><summary>Does “within reach” mean I can definitely retire there?</summary><p>No. It means the financial projection covers the modeled target under the assumptions entered. Immigration, tax, healthcare, currency and personal circumstances can change the conclusion.</p></details><details><summary>Should I model renting or buying?</summary><p>Start with renting if the destination is not yet proven through long stays. Model buying when you have a separate acquisition budget and can verify ownership, financing and transaction costs.</p></details><details><summary>Are visa and tax costs included?</summary><p>No. The finder compares modeled living, reserve and housing capital. Confirm visa eligibility and obtain country-specific tax advice separately.</p></details></section>
</div></div></main>
__FOOTER__
<script type="application/json" id="retirement-finder-data">__PAYLOAD__</script><script>__RETIREMENT_ENGINE__</script><script>__PROPERTY_ENGINE__</script><script>__FINDER_ENGINE__</script><script>__TAX_SCENARIO_ENGINE__</script><script>__FINDER_UI__</script><script>GHARetirementDestinationFinderUI.initRetirementDestinationFinder("retirement-destination-finder",JSON.parse(document.getElementById("retirement-finder-data").textContent));</script>__ANALYTICS__</body></html>"""
    replacements = {
        "__HEAD__": head,
        "__NAV__": navigation,
        "__REGION_OPTIONS__": region_options,
        "__UNIVERSE_COUNT__": str(universe_count),
        "__PAYLOAD__": payload_json,
        "__RETIREMENT_ENGINE__": retirement_engine,
        "__PROPERTY_ENGINE__": property_engine,
        "__FINDER_ENGINE__": finder_engine,
        "__TAX_SCENARIO_ENGINE__": tax_scenario_engine,
        "__FINDER_UI__": finder_ui,
        "__ANALYTICS__": analytics,
        "__DESIGN_CSS__": design_css,
        "__FOOTER__": footer,
    }
    for key, value in replacements.items():
        html = html.replace(key, value)
    return html
